-- Phase 3b: Fuel & Load Safety. Additive PostgreSQL tenant upgrade only.

CREATE TABLE IF NOT EXISTS "GeneratorOperatingLimits" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GeneratorId" integer NOT NULL REFERENCES "Generators" ("Id") ON DELETE RESTRICT,
    "Parameter" integer NOT NULL,
    "Minimum" numeric(18,4),
    "Maximum" numeric(18,4),
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL DEFAULT 0,
    "DeletedAt" timestamp with time zone
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_GeneratorOperatingLimits_Generator_Parameter"
    ON "GeneratorOperatingLimits" ("GeneratorId", "Parameter") WHERE "DeletedAt" IS NULL;

CREATE TABLE IF NOT EXISTS "OverloadEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GeneratorId" integer NOT NULL REFERENCES "Generators" ("Id") ON DELETE RESTRICT,
    "TriggerReadingId" integer NOT NULL REFERENCES "OperationalGeneratorReadings" ("Id") ON DELETE RESTRICT,
    "LatestReadingId" integer NOT NULL,
    "StartedAtUtc" timestamp with time zone NOT NULL,
    "ResolvedAtUtc" timestamp with time zone,
    "PeakPercent" numeric(18,4) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL DEFAULT 0,
    "DeletedAt" timestamp with time zone
);
CREATE INDEX IF NOT EXISTS "IX_OverloadEvents_Generator_Open"
    ON "OverloadEvents" ("GeneratorId", "ResolvedAtUtc");

CREATE TABLE IF NOT EXISTS "OperatingLimitEpisodes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GeneratorOperatingLimitId" integer NOT NULL REFERENCES "GeneratorOperatingLimits" ("Id") ON DELETE RESTRICT,
    "TriggerReadingId" integer NOT NULL REFERENCES "OperationalGeneratorReadings" ("Id") ON DELETE RESTRICT,
    "StartedAtUtc" timestamp with time zone NOT NULL,
    "ResolvedAtUtc" timestamp with time zone,
    "ObservedValue" numeric(18,4) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL DEFAULT 0,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL DEFAULT 0,
    "DeletedAt" timestamp with time zone
);
CREATE INDEX IF NOT EXISTS "IX_OperatingLimitEpisodes_Limit_Open"
    ON "OperatingLimitEpisodes" ("GeneratorOperatingLimitId", "ResolvedAtUtc");
